// frontend/src/pages/Login.jsx
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Eye, EyeOff, Lock, Mail } from "lucide-react";

export default function Login() {
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ email: "", password: "" });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      const res = await fetch("http://localhost:8000/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || "Error al iniciar sesión");
      localStorage.setItem("token", data.access_token);
      navigate("/home");
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#d8e4d0] flex items-center justify-center p-4">
      <div className="bg-[#f5f2ec] rounded-3xl p-8 w-full max-w-sm shadow-sm">

        {/* Ícono hoja */}
        <div className="flex justify-center mb-5">
          <LeafIcon />
        </div>

        <h1 className="text-2xl font-medium text-center text-[#2c3e2d] mb-1">
          Welcome Back
        </h1>
        <p className="text-sm text-center text-[#7a8c7b] mb-7">
          Sign in to continue
        </p>

        {error && (
          <div className="bg-red-50 text-red-600 text-sm rounded-xl px-4 py-2 mb-4">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-3">
          {/* Email */}
          <div className="relative">
            <Mail
              size={16}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-[#6b8f5e] opacity-60"
            />
            <input
              type="email"
              name="email"
              placeholder="Email"
              value={form.email}
              onChange={handleChange}
              required
              className="w-full pl-10 pr-4 py-3 rounded-xl border border-[#c8d4c2] 
                         bg-white text-[#2c3e2d] text-sm outline-none 
                         focus:border-[#6b8f5e] transition-colors"
            />
          </div>

          {/* Password */}
          <div className="relative">
            <Lock
              size={16}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-[#6b8f5e] opacity-60"
            />
            <input
              type={showPassword ? "text" : "password"}
              name="password"
              placeholder="Password"
              value={form.password}
              onChange={handleChange}
              required
              className="w-full pl-10 pr-10 py-3 rounded-xl border border-[#c8d4c2] 
                         bg-white text-[#2c3e2d] text-sm outline-none 
                         focus:border-[#6b8f5e] transition-colors"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-[#6b8f5e] opacity-50"
            >
              {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
            </button>
          </div>

          {/* Forgot */}
          <div className="flex justify-end">
            <Link
              to="/forgot-password"
              className="text-xs text-[#7a8c7b] hover:text-[#6b8f5e]"
            >
              Forgot Password?
            </Link>
          </div>

          {/* Botón */}
          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-[#6b8f5e] hover:bg-[#5a7a4e] text-white 
                       rounded-xl font-medium text-sm transition-colors disabled:opacity-60"
          >
            {loading ? "Signing in..." : "Sign In"}
          </button>
        </form>

        {/* Divider */}
        <div className="flex items-center gap-3 my-4">
          <div className="flex-1 h-px bg-[#c8d4c2]" />
          <span className="text-xs text-[#9aaa9b]">or continue with</span>
          <div className="flex-1 h-px bg-[#c8d4c2]" />
        </div>

        {/* Social */}
        <div className="flex gap-3">
          <button className="flex-1 flex items-center justify-center gap-2 py-2.5 
                             border border-[#c8d4c2] rounded-xl bg-white text-sm text-[#2c3e2d]
                             hover:bg-[#f0ede6] transition-colors">
            {/* Google SVG */}
            <GoogleIcon /> Google
          </button>
          <button className="flex-1 flex items-center justify-center gap-2 py-2.5 
                             border border-[#c8d4c2] rounded-xl bg-white text-sm text-[#2c3e2d]
                             hover:bg-[#f0ede6] transition-colors">
            <AppleIcon /> Apple
          </button>
        </div>

        <p className="text-center text-sm text-[#7a8c7b] mt-5">
          Don't have an account?{" "}
          <Link to="/register" className="text-[#6b8f5e] font-medium hover:underline">
            Sign Up
          </Link>
        </p>
      </div>
    </div>
  );
}

// Componentes auxiliares de íconos
function LeafIcon() {
  return (
    <svg width="72" height="72" viewBox="0 0 80 80" fill="none">
      <ellipse cx="40" cy="35" rx="18" ry="26" fill="#8aad7a" opacity="0.85" transform="rotate(-8 40 35)" />
      <ellipse cx="42" cy="33" rx="14" ry="22" fill="#6b8f5e" opacity="0.7" transform="rotate(6 42 33)" />
      <line x1="40" y1="60" x2="40" y2="72" stroke="#6b8f5e" strokeWidth="2" strokeLinecap="round" />
      <line x1="40" y1="38" x2="33" y2="28" stroke="#8aad7a" strokeWidth="1.2" strokeLinecap="round" opacity="0.6" />
      <line x1="40" y1="44" x2="47" y2="34" stroke="#8aad7a" strokeWidth="1.2" strokeLinecap="round" opacity="0.6" />
    </svg>
  );
}

function GoogleIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24">
      <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
      <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
      <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
      <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
    </svg>
  );
}

